abstract class TFMListValuesAndDataTable extends TFMRegistrationCollector implements TFMListValuesInterface, TFMDataTableInterface
{
    str ListValues;
    str ListSeparator;
    str dataTable;
    str dataKeyColumn;
    str dataDisplayColumn;
    int dataLinkedElement;
    str filterColumn;
    int linkedElement;
    str linkColumn;

}

Method.Source:
[TFMCategory("@SYS72248", "A human readable version of the key value")]
public str parmDataDisplayColumn(str _dataDisplayColumn = dataDisplayColumn)
{
    dataDisplayColumn = _dataDisplayColumn;
    return dataTable ? (dataDisplayColumn ? dataDisplayColumn : 'value') : '';
}

[TFMCategory("@SYS101115", "The list seperator character if in the ListValues configuration.")]
public str parmListSeparator(str _ListSeparator = ListSeparator)
{
    ListSeparator = _ListSeparator;
    return ListSeparator;
}

[TFMCategory("@SYS101115", "The values that the list contains seperated by what has been set up in the ListSeparator configuration")]
public str parmListValues(str _ListValues = ListValues)
{
    ListValues = _ListValues;
    return ListValues;
}

[TFMCategory("@SYS103414")]
public boolean parmVisible(boolean _visible = visible)
{
    boolean ret;

    ret = super(_visible);

    if (ret && !dataTable && ListValues && TFMHelper::strSplit(ListValues, ListSeparator).elements() == 1)
    {
        this.parmDefaultValue(ListValues);
        return false;
    }

    return ret;
}

public str parmDefaultValue(str _defaultDate = defaultValue)
{
    str ret;

    ret = super(_defaultDate);

    if (!ret && !dataTable && ListValues && TFMHelper::strSplit(ListValues, ListSeparator).elements() == 1)
    {
        ret = ListValues;
    }

    return ret;
}

    public void map2ListValues(Map _listvalues)
    {
        MapEnumerator	mEnum = _listvalues.getEnumerator();

        ListValues = '';

		while (mEnum.moveNext())
        {
            ListValues += (ListValues ? ListSeparator : '') + mEnum.currentKey();
        }
    }

[TFMCategory("@SYS72248", "When using the 'dataTable' over 'listValues', make sure to also configure 'dataKeyColumn' and 'dataDisplayColumn'.")]
public str parmDataTable(str _dataTable = dataTable)
{
    dataTable = _dataTable;
    return dataTable;
}

[TFMCategory("@SYS72248", "The column in the slave table to filter values by. The specific value is defined by the selection in the master field.")]
public str parmFilterColumn(str _filterColumn = filterColumn)
{
    filterColumn = _filterColumn;
    return filterColumn;
}

[TFMCategory("@SYS72248", "A column from the master table, from which the slave field will get it's value once input changes on the master field.")]
public str parmLinkColumn(str _linkColumn = linkColumn)
{
    linkColumn = _linkColumn;
    return linkColumn;
}

[TFMCategory("@SYS72248", "The name of the column that will be used when sending requests to the backend and linking fields.")]
public str parmDataKeyColumn(str _dataKeyColumn = dataKeyColumn)
{
    dataKeyColumn = _dataKeyColumn;
    return dataTable ? (dataKeyColumn ? dataKeyColumn : 'id') : '';
}

[TFMCategory("@SYS72248")]
public int parmDataLinkedElement(int _dataLinkedElement = dataLinkedElement)
{
    dataLinkedElement = _dataLinkedElement;
    return dataLinkedElement;
}

[TFMCategory("@SYS72248", "The Id of the slave field that is affected by input in this field.")]
public int parmLinkedElement(int _LinkedElement = linkedElement)
{
    linkedElement = _linkedElement;
    return linkedElement;
}

public void new(int _id, str _name, str _header, str _label, str _helpLabel)
{
    super(_id, _name, _header, _label, _helpLabel);
    dataLinkedElement = -5;
    ListSeparator = ';';
    linkedElement = -5;
}
